class InputReader(private val list: List<String>) {
    var index = 0
    val max = list.size

    fun hasNext(): Boolean = index < max

    fun next(): String {
        if (hasNext()) {
            return list[index++]
        } else {
            throw ArrayIndexOutOfBoundsException("There is no more input")
        }
    }
}

fun nextInt(): Int = myconv(next(), 1) as Int
