fun myconv(i: Any, no: Int): Any {
    return try {
        when (no) {
            1 -> (i as String).toInt()
            2 -> (i as String).split(" ")
            4 -> (i as String).split(" ").map { it.toInt() }
            6 -> (i as String).map { it }
            7 -> (i as String).map { it.toString().toInt() }
            8 -> (i as List<String>).joinToString(" ")
            9 -> (i as List<String>).joinToString("\n")
            0 -> (i as List<String>).joinToString("")
            else -> i
        }
    } catch (e: Exception) {
        i
    }
}

